/*
 * A036577  Ternary Thue-Morse sequence: closed under a->abc, b->ac, c->b.
 * https://oeis.org/A036577
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth symbol of the morphic word generated by a → a b
 *            c, b → a c, c → b, with the encoding a=2, b=1, c=0. The word is
 *            built by repeated substitution starting from a single “a” symbol
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of the morphic word; symbols are stored as 0,1,2 */
    static seq_t *seq = NULL;
    static size_t len = 0;

    if (n < 1)                 /* offset 1 – undefined for n < 1 */
        return 0;

    /* initialise the cache on first call */
    if (len == 0) {
        seq = (seq_t *)malloc(sizeof(seq_t));
        if (!seq) return 0;
        seq[0] = 0;            /* start with a */
        len = 1;
    }

    /* expand the word until it reaches at least the requested index */
    while (len < n) {
        /* compute length after one substitution step */
        size_t new_len = 0;
        for (size_t i = 0; i < len; ++i) {
            seq_t s = seq[i];
            if (s == 0)          /* a → abc */
                new_len += 3;
            else if (s == 1)      /* b → ac */
                new_len += 2;
            else                  /* c → b */
                new_len += 1;
        }

        seq_t *new_seq = (seq_t *)malloc(new_len * sizeof(seq_t));
        if (!new_seq) return 0;

        /* fill new_seq with the expansion of seq */
        size_t p = 0;
        for (size_t i = 0; i < len; ++i) {
            seq_t s = seq[i];
            if (s == 0) {            /* a → a b c */
                new_seq[p++] = 0;    /* a */
                new_seq[p++] = 1;    /* b */
                new_seq[p++] = 2;    /* c */
            } else if (s == 1) {     /* b → a c */
                new_seq[p++] = 0;    /* a */
                new_seq[p++] = 2;    /* c */
            } else {                 /* c → b */
                new_seq[p++] = 1;    /* b */
            }
        }

        free(seq);
        seq = new_seq;
        len = new_len;
    }

    /* retrieve the symbol at position n-1 (0‑based) */
    seq_t sym = seq[(size_t)(n - 1)];

    /* map a→2, b→1, c→0 and return the value */
    return (sym == 0) ? 2 : ((sym == 1) ? 1 : 0);
}
